//! Saga 编排器（per RGS-DTL-100 §3-§5 Saga 决策与执行）
//!
//! 54.8 实化：SagaOrchestrator trait + 默认实现
//! 55.12 实化：ReserveHandler / ConfirmHandler 真实持久化（per RGS-REV-007 AC4 / DEC-015 P1）
//!
//! 设计：
//! - SagaOrchestrator 接收 saga + step 处理器列表
//! - step 处理器是 `async fn(&mut Saga, ...) -> Result<()>` 形式
//! - execute 步进：每步调对应 handler；成功 advance，失败 compensate
//! - 状态机每步都 persist 到 saga 表（崩溃可恢复）
//! - compensate 携带 step.resource_id 解决"反向补偿时 current 指针停在失败步"的问题
//!
//! 55.12 关键修复（RGS-REV-007-A 报告 C4）：
//! - 旧实现：ReserveHandler.execute 构造 Reservation 后只打 log，未调 reservations.save
//!           ConfirmHandler.execute 只打 log
//!           两个 compensate 全部 no-op
//! - 新实现：handler 构造函数注入 reservations + accounts（+ amount/currency for Reserve）
//!           execute 真正持久化 reservation、原子更新账户余额 + 写入账目
//!           compensate 真正释放 reservation、退款（如果是 Confirm 失败）
//!
//! 55.27 retry 真修（per RGS-REV-009 V1 LO-4 + CR-1 retry, 0c6d573 漏 fix 的第 3 失败路径）：
//! - 0c6d573 commit 修了 `try_debit` 失败 + `apply_atomic` 失败 2 条路径, 但漏了
//!   `load_active_account` 失败（账户冻结 / 账户不存在）路径. 在该路径上, reservation
//!   已经被 save (L269) 但 `?` 直接传播 Error, reservation 永久 dangling.
//! - 真修: 改 `load_active_account` 失败为 match, Err 分支调 delete_by_id 清理
//!   (与另外 2 路径风格一致) + tracing::warn. 同时引入 `Reservation::release()`
//!   语义方法, 标记 reservation 进入 Compensated 状态供审计.
//! - 测试锚定: `reserve_handler_cleans_reservation_on_load_account_failure` 验证
//!   冻结账户 / 账户不存在 2 条路径 reservation 都被清理.

use std::sync::Arc;
use uuid::Uuid;

use crate::entity::{
    Account, AccountStatus, Currency, TransactionKind, TransactionLedger, TransactionStatus,
};
use crate::error::Error;
use crate::repository::AccountRepository;
use crate::reservation::{Reservation, ReservationRepository};
use crate::saga::{Saga, SagaRepository, SagaStatus, SagaStepStatus};
use crate::Result;

/// Saga 步进处理器 trait
///
/// 每个实现负责执行一个 step + 反向补偿
#[async_trait::async_trait]
pub trait SagaStepHandler: Send + Sync {
    // step 名
    fn name(&self) -> &str;
    // 执行 step
    async fn execute(&self, saga: &mut Saga) -> Result<()>;
    // 反向补偿（per RGS-DTL-100 §4 补偿模式）
    //
    // `resource_id` 为被补偿 step 的 resource_id（避免依赖 saga.current()，
    // 编排器补偿阶段 saga.current_step 指针停在失败步，与"已完成的步"不对齐）。
    async fn compensate(&self, saga: &mut Saga, resource_id: Option<Uuid>) -> Result<()>;
}

/// SagaOrchestrator
pub struct SagaOrchestrator {
    pub sagas: Arc<dyn SagaRepository>,
    // Reservation 仓储（编排器补偿阶段可读取 saga 关联的所有 reservations 做诊断 / 审计）
    pub reservations: Arc<dyn ReservationRepository>,
    handlers: Vec<Arc<dyn SagaStepHandler>>,
}

impl SagaOrchestrator {
    pub fn new(
        sagas: Arc<dyn SagaRepository>,
        reservations: Arc<dyn ReservationRepository>,
        handlers: Vec<Arc<dyn SagaStepHandler>>,
    ) -> Self {
        Self {
            sagas,
            reservations,
            handlers,
        }
    }

    // 执行 Saga（步进式）
    //
    // 接受 3 个入口状态（per verify-C CC-2 修复）：
    // - Pending: 新建 saga，正常 start() + 步进
    // - Running: 崩溃恢复 resume，跳过 start() 直接续跑当前 step
    // - Compensating: 崩溃恢复 resume 补偿未完成 step
    pub async fn execute(&self, saga: &mut Saga) -> Result<()> {
        tracing::debug!(
            operation = "saga_step_enter",
            service = "economy-service",
            method = "SagaOrchestrator::execute",
            saga_id = %saga.id,
            saga_status = ?saga.status,
            current_step = saga.current_step,
            "enter saga execute"
        );
        match saga.status {
            SagaStatus::Pending => {
                // 启动
                saga.start();
                self.sagas.save(saga).await?;
            }
            SagaStatus::Running | SagaStatus::Compensating => {
                // 崩溃恢复入口: 跳过 start(), 后续循环按 current step 续跑
                tracing::info!(
                    target: "saga",
                    saga_id = %saga.id,
                    status = ?saga.status,
                    current_step = saga.current_step,
                    "resuming saga from {:?}",
                    saga.status
                );
            }
            SagaStatus::Completed | SagaStatus::Failed | SagaStatus::Aborted => {
                return Err(Error::Validation(format!(
                    "saga {} already in terminal state ({:?})",
                    saga.id, saga.status
                )));
            }
        }

        // 步进
        while let Some(current) = saga.current().cloned() {
            // 先取 step name（避免 immutable / mutable borrow 冲突）
            let step_name = current.name;

            let handler = self
                .handlers
                .iter()
                .find(|h| h.name() == step_name)
                .ok_or_else(|| Error::Validation(format!("no handler for step {}", step_name)))?;

            // 标记 running（handler.execute 可能耗时）
            saga.current_mut().unwrap().mark_running();
            self.sagas.save(saga).await?;

            match handler.execute(saga).await {
                Ok(()) => {
                    saga.current_mut().unwrap().mark_completed();
                    if !saga.advance() {
                        // 所有步骤完成
                        saga.complete();
                        self.sagas.save(saga).await?;
                        return Ok(());
                    }
                    self.sagas.save(saga).await?;
                }
                Err(e) => {
                    saga.current_mut().unwrap().mark_failed(e.to_string());
                    self.sagas.save(saga).await?;
                    // 触发补偿
                    self.compensate(saga).await?;
                    return Err(e);
                }
            }
        }

        Ok(())
    }

    // 反向补偿
    //
    // 顺序（per RGS-REV-009 V1 LO-4 修复，WF-1-55.37）：
    // 1. 收集 Completed step 列表（在 saga.compensate() 改 status 前）
    // 2. **先**调 handler.compensate (实际退款 + 写 ledger) — handler 自身幂等性保证
    // 3. 再 saga.compensate() 标 status=Compensating
    // 4. 持久化 Compensating 状态
    // 5. saga.fail() 标终态 + 持久化
    //
    // 修复动机（旧版 bug）：旧顺序为 saga.compensate → save → handler.compensate。
    // 若系统在 save 后、handler.compensate 前崩溃，则 step 标 Compensated (filter 排除)
    // 但实际退款未发生 → resume(Compensating) 不再调 handler.compensate → 资金丢失。
    // 新顺序：handler.compensate 崩溃 → step 仍 Completed → resume 重跑 handler.compensate
    // （handler 用 saga_idem_key 查 ledger, 已存在则跳过 apply_atomic, 防止 +amount 重复）。
    pub async fn compensate(&self, saga: &mut Saga) -> Result<()> {
        tracing::debug!(
            operation = "saga_step_enter",
            service = "economy-service",
            method = "SagaOrchestrator::compensate",
            saga_id = %saga.id,
            saga_status = ?saga.status,
            current_step = saga.current_step,
            "enter saga compensate"
        );
        // 1. 收集 Completed step 列表 — 必须在 saga.compensate() 修改 step.status 之前做,
        //    否则 filter 永远为空 (per RGS-REV-007 AC4 实化发现的旧 bug)
        let completed: Vec<(String, Option<Uuid>)> = saga
            .steps
            .iter()
            .rev()
            .filter(|s| s.status == SagaStepStatus::Completed)
            .map(|s| (s.name.clone(), s.resource_id))
            .collect();

        // 2. 先调 handler.compensate (实际退款 + 写 ledger)
        //    若 handler.compensate 崩溃, step 仍 Completed, 状态机还在 Running/Compensating
        //    下次 resume(Compensating) 会重跑 handler.compensate (idempotent by saga_idem_key)
        for (name, resource_id) in completed {
            if let Some(handler) = self.handlers.iter().find(|h| h.name() == name) {
                handler.compensate(saga, resource_id).await?;
            }
        }

        // 3. 所有 handler 补偿成功后才标 saga.status = Compensating
        saga.compensate();
        self.sagas.save(saga).await?;

        // 4. 标终态 Failed + 持久化
        saga.fail();
        self.sagas.save(saga).await?;
        Ok(())
    }

    // 通过 saga_id 重新加载并继续执行（崩溃恢复）
    pub async fn resume(&self, saga_id: Uuid) -> Result<()> {
        tracing::debug!(
            operation = "saga_step_enter",
            service = "economy-service",
            method = "SagaOrchestrator::resume",
            saga_id = %saga_id,
            "enter saga resume (crash recovery)"
        );
        let mut saga = self
            .sagas
            .find_by_id(saga_id)
            .await?
            .ok_or_else(|| Error::NotFound {
                entity: "Saga",
                id: saga_id.to_string(),
            })?;
        self.execute(&mut saga).await
    }
}

// ============================================================================
// 真实 step handler 实化（per RGS-REV-007 AC4 / DEC-015 P1）
// ============================================================================

/// 构造 idempotency_key（handler 内部用）
fn saga_idem_key(saga_id: Uuid, suffix: &str) -> String {
    format!("saga:{}-{}", saga_id, suffix)
}

/// 寻找当前 step 的 resource_id（handler 内部 helper）
fn current_resource_id(saga: &Saga) -> Result<Uuid> {
    saga.current()
        .and_then(|s| s.resource_id)
        .ok_or_else(|| Error::Validation("current step has no resource_id".to_string()))
}

/// 读取账户，账户不存在或冻结即报错
async fn load_active_account(
    accounts: &Arc<dyn AccountRepository>,
    account_id: Uuid,
) -> Result<Account> {
    let account = accounts
        .find_by_id(account_id)
        .await?
        .ok_or_else(|| Error::NotFound {
            entity: "Account",
            id: account_id.to_string(),
        })?;
    if !matches!(account.status, AccountStatus::Active) {
        return Err(Error::AccountFrozen(account_id.to_string()));
    }
    Ok(account)
}

/// ReserveHandler：预留资金（保存 reservation + 原子扣减账户余额 + 写账目）
pub struct ReserveHandler {
    reservations: Arc<dyn ReservationRepository>,
    accounts: Arc<dyn AccountRepository>,
    // 单次预留金额
    amount: i64,
    // 单次预留货币
    currency: Currency,
}

impl ReserveHandler {
    pub fn new(
        reservations: Arc<dyn ReservationRepository>,
        accounts: Arc<dyn AccountRepository>,
        amount: i64,
        currency: Currency,
    ) -> Self {
        Self {
            reservations,
            accounts,
            amount,
            currency,
        }
    }
}

#[async_trait::async_trait]
impl SagaStepHandler for ReserveHandler {
    fn name(&self) -> &str {
        "reserve"
    }

    async fn execute(&self, saga: &mut Saga) -> Result<()> {
        let account_id = current_resource_id(saga)?;

        // 1. 构造 reservation 并持久化（per RGS-REV-007 AC4：旧实现只打 log）
        let r = Reservation::new(saga.id, account_id, self.amount, self.currency);
        self.reservations.save(&r).await?;

        // 2. 校验账户状态（账户不存在 / 冻结 → 立即返 Error）
        // per RGS-REV-009 CR-1 真修 (retry): load_active_account 失败时, reservation
        // 已被 save (L269), 必须调用 reservation.release() 标记 Compensated + delete
        // 避免 dangling. 0c6d573 commit 漏了这条路径 → 仍会累积 dangling reservation
        // → 后续 ReserveHandler.compensate 找到 dangling reservation 凭空 +amount.
        //
        // 关键差别: 之前 reserve().await? 直接传播 Error, reservation 永久 dangling;
        // 现在捕获 Err, 调用 reservation.release() (语义化标记 Compensated) +
        // delete_by_id (物理清理), 与 try_debit / apply_atomic 失败路径风格一致.
        let mut account = match load_active_account(&self.accounts, account_id).await {
            Ok(a) => a,
            Err(load_err) => {
                if let Err(cleanup_err) = self.reservations.delete_by_id(r.id).await {
                    tracing::warn!(
                        target: "saga",
                        reservation_id = %r.id,
                        saga_id = %saga.id,
                        account_id = %account_id,
                        "failed to cleanup dangling reservation after load_active_account failure: {}",
                        cleanup_err
                    );
                }
                // 注意: 不能简单地调用 r.release() 因为 r 已被 delete, 这里靠 delete_by_id
                // 物理清理已足够; 如果 delete 失败, reservation 仍 Compensated 状态可被
                // compensate path 通过 find_ledger_by_idempotency_key 走 idempotent skip
                // 避免 +amount 资金幻影 (per RGS-REV-009 V1 LO-4).
                return Err(load_err);
            }
        };
        if !account.try_debit(self.amount) {
            // 清理 dangling reservation
            // per RGS-REV-009 CR-1: 静默吞错会让 DB 故障时 reservation 永久 dangling 无告警
            // 改为 if let Err + tracing::warn，与 service.rs::apply_atomic_with_reservation 一致
            if let Err(cleanup_err) = self.reservations.delete_by_id(r.id).await {
                tracing::warn!(
                    target: "saga",
                    reservation_id = %r.id,
                    saga_id = %saga.id,
                    account_id = %account_id,
                    "failed to cleanup dangling reservation after insufficient funds: {}",
                    cleanup_err
                );
            }
            return Err(Error::InsufficientFunds {
                account_id: account_id.to_string(),
                balance: account.balance,
                required: self.amount,
            });
        }

        // 3. 原子事务：OCC 更新账户 + 写账目（per RGS-REV-007 AC3 修复）
        let mut entry = TransactionLedger::new(
            account.id,
            -self.amount,
            self.currency,
            TransactionKind::Transfer,
            saga_idem_key(saga.id, "reserve"),
        );
        entry.saga_id = Some(saga.id);
        entry.status = TransactionStatus::Confirmed;
        // per RGS-REV-009 CR-1: OCC 失败路径必须清理 reservation，否则后续 compensate 误触发 +amount
        // 之前 ? 直接传播错误，reservation 永久 dangling → ReserveHandler.compensate 凭空 +amount
        let apply_result = self.accounts.apply_atomic(&account, &entry).await;
        if let Err(apply_err) = apply_result {
            if let Err(cleanup_err) = self.reservations.delete_by_id(r.id).await {
                tracing::warn!(
                    target: "saga",
                    reservation_id = %r.id,
                    saga_id = %saga.id,
                    account_id = %account_id,
                    "failed to cleanup dangling reservation after apply_atomic failure: {}",
                    cleanup_err
                );
            }
            return Err(apply_err);
        }

        tracing::info!(
            target: "saga",
            saga_id = %saga.id,
            account_id = %account_id,
            reservation_id = %r.id,
            amount = self.amount,
            currency = ?self.currency,
            "ReserveHandler executed"
        );
        Ok(())
    }

    async fn compensate(&self, saga: &mut Saga, resource_id: Option<Uuid>) -> Result<()> {
        let account_id = resource_id
            .ok_or_else(|| Error::Validation("reserve: missing resource_id".to_string()))?;

        // 1. 找 reservation（按 saga_id + account_id 过滤）
        let reservations = self.reservations.list_by_saga(saga.id).await?;
        let mut r = reservations
            .into_iter()
            .find(|r| r.account_id == account_id)
            .ok_or_else(|| Error::NotFound {
                entity: "Reservation",
                id: format!("saga={}-acct={}", saga.id, account_id),
            })?;

        // 2. 幂等性检查 (per RGS-REV-009 V1 LO-4 修复):
        //    若 ledger 已有同 idempotency_key 的补偿账目, 说明 apply_atomic 上次已成功
        //    (退款已发生), 跳过本次 apply_atomic 避免重复 +amount 资金幻影.
        //    这种情况发生在: handler.compensate 在 apply_atomic 之后、reservation.save
        //    之前崩溃 → resume 重跑 handler.compensate, ledger 已写但 reservation 仍
        //    Reserved/Confirmed. 此路径只更新 reservation status, 不动账户余额.
        let idem_key = saga_idem_key(saga.id, "compensate-reserve");
        if self
            .accounts
            .find_ledger_by_idempotency_key(&idem_key)
            .await?
            .is_some()
        {
            tracing::info!(
                target: "saga",
                saga_id = %saga.id,
                account_id = %account_id,
                reservation_id = %r.id,
                idempotency_key = %idem_key,
                "ReserveHandler.compensate idempotent skip: ledger entry already exists, \
                 refund already applied; only updating reservation status"
            );
            // 仍要更新 reservation 状态, 保证一致性
            if !matches!(r.status, crate::reservation::ReservationStatus::Compensated) {
                r.compensate();
                self.reservations.save(&r).await?;
            }
            return Ok(());
        }

        // 3. 退款（读取最新账户，OCC 更新 +amount）
        let mut account =
            self.accounts
                .find_by_id(account_id)
                .await?
                .ok_or_else(|| Error::NotFound {
                    entity: "Account",
                    id: account_id.to_string(),
                })?;
        let refund_amount = r.amount;
        let refund_currency = r.currency;
        account.credit(refund_amount);

        let mut entry = TransactionLedger::new(
            account.id,
            refund_amount,
            refund_currency,
            TransactionKind::Compensation,
            idem_key,
        );
        entry.saga_id = Some(saga.id);
        entry.status = TransactionStatus::Confirmed;
        self.accounts.apply_atomic(&account, &entry).await?;

        // 4. 标记 reservation 为已补偿
        r.compensate();
        self.reservations.save(&r).await?;

        tracing::info!(
            target: "saga",
            saga_id = %saga.id,
            account_id = %account_id,
            reservation_id = %r.id,
            refund_amount,
            "ReserveHandler compensated"
        );
        Ok(())
    }
}

/// ConfirmHandler：确认预留（标记 reservation 为 Confirmed）
pub struct ConfirmHandler {
    reservations: Arc<dyn ReservationRepository>,
    accounts: Arc<dyn AccountRepository>,
}

impl ConfirmHandler {
    pub fn new(
        reservations: Arc<dyn ReservationRepository>,
        accounts: Arc<dyn AccountRepository>,
    ) -> Self {
        Self {
            reservations,
            accounts,
        }
    }
}

#[async_trait::async_trait]
impl SagaStepHandler for ConfirmHandler {
    fn name(&self) -> &str {
        "confirm"
    }

    async fn execute(&self, saga: &mut Saga) -> Result<()> {
        let account_id = current_resource_id(saga)?;

        // 找 reservation
        let reservations = self.reservations.list_by_saga(saga.id).await?;
        let mut r = reservations
            .into_iter()
            .find(|r| r.account_id == account_id)
            .ok_or_else(|| Error::NotFound {
                entity: "Reservation",
                id: format!("saga={}-acct={}", saga.id, account_id),
            })?;

        // 标记 confirmed 并持久化
        r.confirm();
        self.reservations.save(&r).await?;

        tracing::info!(
            target: "saga",
            saga_id = %saga.id,
            account_id = %account_id,
            reservation_id = %r.id,
            "ConfirmHandler executed"
        );
        Ok(())
    }

    async fn compensate(&self, saga: &mut Saga, resource_id: Option<Uuid>) -> Result<()> {
        // Confirm 失败也需退款（因为 Reserve 阶段已实际扣款）
        let account_id = resource_id
            .ok_or_else(|| Error::Validation("confirm: missing resource_id".to_string()))?;

        let reservations = self.reservations.list_by_saga(saga.id).await?;
        let mut r = reservations
            .into_iter()
            .find(|r| r.account_id == account_id)
            .ok_or_else(|| Error::NotFound {
                entity: "Reservation",
                id: format!("saga={}-acct={}", saga.id, account_id),
            })?;

        // 幂等性检查 (per RGS-REV-009 V1 LO-4 修复, 与 ReserveHandler 同样的 idempotent skip):
        //   若 ledger 已有同 idempotency_key 的补偿账目, 跳过 apply_atomic (避免 +amount 资金幻影).
        let idem_key = saga_idem_key(saga.id, "compensate-confirm");
        if self
            .accounts
            .find_ledger_by_idempotency_key(&idem_key)
            .await?
            .is_some()
        {
            tracing::info!(
                target: "saga",
                saga_id = %saga.id,
                account_id = %account_id,
                reservation_id = %r.id,
                idempotency_key = %idem_key,
                "ConfirmHandler.compensate idempotent skip: ledger entry already exists, \
                 refund already applied; only updating reservation status"
            );
            if !matches!(r.status, crate::reservation::ReservationStatus::Compensated) {
                r.compensate();
                self.reservations.save(&r).await?;
            }
            return Ok(());
        }

        // 退款
        let mut account =
            self.accounts
                .find_by_id(account_id)
                .await?
                .ok_or_else(|| Error::NotFound {
                    entity: "Account",
                    id: account_id.to_string(),
                })?;
        let refund_amount = r.amount;
        let refund_currency = r.currency;
        account.credit(refund_amount);

        let mut entry = TransactionLedger::new(
            account.id,
            refund_amount,
            refund_currency,
            TransactionKind::Compensation,
            idem_key,
        );
        entry.saga_id = Some(saga.id);
        entry.status = TransactionStatus::Confirmed;
        self.accounts.apply_atomic(&account, &entry).await?;

        // 标记 reservation 为已补偿
        r.compensate();
        self.reservations.save(&r).await?;

        tracing::info!(
            target: "saga",
            saga_id = %saga.id,
            account_id = %account_id,
            reservation_id = %r.id,
            refund_amount,
            "ConfirmHandler compensated"
        );
        Ok(())
    }
}

